import sys

def main():
    import sys
    import math

    def read_ints():
        return list(map(int, sys.stdin.readline().split()))

    def read_str():
        return sys.stdin.readline().strip()

    Tg, Ty, Tr = read_ints()
    n = read_ints()[0]
    observations = [read_str().split() for _ in range(n)]
    tq, cq = read_str().split()
    tq = int(tq)

    # Convert observations to a list of tuples (time, color)
    observations = [(int(t), c) for t, c in observations]

    # Calculate the total cycle length
    cycle_length = Tg + Ty + Tr

    # Initialize a list to store the intervals for each color
    intervals = {'green': [], 'yellow': [], 'red': []}

    # Process each observation to determine the intervals
    for i, (t, c) in enumerate(observations):
        if i == 0:
            # First observation sets the initial interval
            intervals[c].append((0, t))
        else:
            prev_t, prev_c = observations[i - 1]
            if prev_c != c:
                # Determine the start and end of the new interval
                start = prev_t % cycle_length
                end = t % cycle_length
                if start < end:
                    intervals[c].append((start, end))
                else:
                    # Interval wraps around the cycle
                    intervals[c].append((start, cycle_length))
                    intervals[c].append((0, end))

    # Merge overlapping intervals for each color
    for color in intervals:
        intervals[color] = merge_intervals(intervals[color])

    # Calculate the total length of intervals for the query color
    total_length = sum(end - start for start, end in intervals[cq])

    # Calculate the probability
    probability = total_length / cycle_length

    # Print the result with the required precision
    print(f"{probability:.3f}")

def merge_intervals(intervals):
    if not intervals:
        return []

    # Sort intervals by their start time
    intervals.sort()

    merged = [intervals[0]]
    for current in intervals[1:]:
        last_merged = merged[-1]
        if current[0] <= last_merged[1]:
            # Overlapping intervals, merge them
            merged[-1] = (last_merged[0], max(last_merged[1], current[1]))
        else:
            # Non-overlapping interval, add it to the merged list
            merged.append(current)

    return merged

