def calculate_probability(Tg, Ty, Tr, observations, t_q, c_q):
    total_cycle_time = Tg + Ty + Tr
    possible_T_values = []

    for t, color in observations:
        if color == 'green':
            start = t % total_cycle_time
            if start < Tg:
                possible_T_values.append(start)
        elif color == 'yellow':
            start = t % total_cycle_time
            if Tg <= start < Tg + Ty:
                possible_T_values.append(start - Tg)
        elif color == 'red':
            start = t % total_cycle_time
            if Tg + Ty <= start < total_cycle_time:
                possible_T_values.append(start - Tg - Ty)

    possible_T_values = list(set(possible_T_values))
    possible_T_values.sort()

    if not possible_T_values:
        return 0.0

    valid_intervals = []
    for i in range(len(possible_T_values)):
        start = possible_T_values[i]
        end = start + total_cycle_time
        if t_q >= start and t_q < end:
            valid_intervals.append((start, end))

    if not valid_intervals:
        return 0.0

    total_valid_time = 0
    for start, end in valid_intervals:
        if c_q == 'green':
            total_valid_time += min(end, t_q + Tg) - max(start, t_q)
        elif c_q == 'yellow':
            total_valid_time += min(end, t_q + Ty) - max(start + Tg, t_q)
        elif c_q == 'red':
            total_valid_time += min(end, t_q + Tr) - max(start + Tg + Ty, t_q)

    return total_valid_time / len(valid_intervals)

